    private String shortSecurityStatus(){String value=engine==null?"Preparing secure messaging…":engine.status();if(value.startsWith("All ")&&value.contains("app-checked"))return "Encryption ready · device keys checked";if(value.contains("changed"))return "Security change · sending blocked";if(value.contains("not published"))return "Recipient keys unavailable";if(value.startsWith("No active"))return "No active recipient devices";if(value.startsWith("Archived"))return "Archived · read only";return value;}
    private void render(){if(!started||messages==null)return;runOnUiThread(()->{try{int oldScrollY=messageScroll.getScrollY(),oldContentHeight=messages.getHeight();int oldRange=Math.max(0,oldContentHeight-messageScroll.getHeight());boolean wasNearBottom=oldRange-oldScrollY<dp(48);status.setText(shortSecurityStatus());if(contact.optBoolean("deleted")){String name=contact.optString("display_name","Conversation");setTitle(name);composer.setEnabled(false);send.setEnabled(false);attach.setEnabled(false);}JSONArray rows=engine.messages();messages.removeAllViews();ArrayList<TimelineItem> timeline=new ArrayList<>();String baseName=contact.optString("display_name","this person").replaceFirst("\\s+\\(Deleted User\\)$","");String connected=contact.optString("connected_at","");if(!connected.isEmpty())timeline.add(new TimelineItem("connection-event",connected,null,"You and "+baseName+" are now friends."));for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(row!=null)timeline.add(row.optBoolean("system")?new TimelineItem(row.optString("id",Integer.toString(i)),row.optString("created_at",""),null,row.optString("text")):new TimelineItem(row.optString("id",Integer.toString(i)),row.optString("created_at",""),row,null));}if(contact.optBoolean("deleted")){String deletedAt=contact.optString("deleted_at","");if(!deletedAt.isEmpty())timeline.add(new TimelineItem("deleted-event",deletedAt,null,baseName+" deleted his account. No new messages are allowed."));}timeline.sort((a,b)->{int order=a.createdAt.compareTo(b.createdAt);return order!=0?order:a.id.compareTo(b.id);});String previousDay="";for(TimelineItem item:timeline){String day=localDay(item.createdAt);if(!day.equals(previousDay)){renderDaySeparator(item.createdAt);previousDay=day;}if(item.eventText!=null)renderSystemEvent(item.eventText,item.createdAt);else renderMessage(item.message);}messageScroll.post(()->{if(wasNearBottom)messageScroll.fullScroll(View.FOCUS_DOWN);else messageScroll.scrollTo(0,oldScrollY+Math.max(0,messages.getHeight()-oldContentHeight));loadVisibleInlineGifs();});}catch(Exception error){status.setText("Encrypted local history could not be displayed.");}});}
