        TextView meta=SereinUi.text(this,mine?deliverySummary(row):formatEventDate(row.optString("created_at")),10,mine&&SereinUi.isDark(this)?0xFFB9D9D0:SereinUi.muted(this),false);meta.setGravity(Gravity.END);bubble.addView(meta);if(mine&&"expired".equals(row.optString("status"))){Button retry=SereinUi.button(this,row.has("attachment")?"Select file to retry":"Retry message",false);bubble.addView(retry,SereinUi.margin(this,-1,40,0,5,0,0));retry.setOnClickListener(v->{if(row.has("attachment")){toast("Choose the original file again; attachment bytes may have expired.");pickFile();return;}retry.setEnabled(false);engine.retryExpiredMessage(row.optString("id")).whenComplete((ignored,error)->runOnUiThread(()->{retry.setEnabled(true);if(error!=null)toast(safeError(error));else status.setText(engine.status());render();}));});}
