    private void loadVisibleInlineGifs(){if(messageScroll==null||engine==null||!engine.ready()||contact==null||contact.optBoolean("deleted"))return;int[] viewport=new int[2];messageScroll.getLocationOnScreen(viewport);int top=viewport[1],bottom=top+messageScroll.getHeight();for(int i=0;i<messages.getChildCount();i++){View row=messages.getChildAt(i);if(!(row instanceof LinearLayout))continue;LinearLayout line=(LinearLayout)row;if(line.getChildCount()==0)continue;View bubble=line.getChildAt(line.getChildCount()-1);if(!(bubble instanceof LinearLayout))continue;LinearLayout contents=(LinearLayout)bubble;for(int j=0;j<contents.getChildCount();j++){View child=contents.getChildAt(j);Object tag=child.getTag();if(!(tag instanceof JSONObject))continue;int[] location=new int[2];child.getLocationOnScreen(location);if(location[1]+child.getHeight()<top||location[1]>bottom)continue;JSONObject attachment=(JSONObject)tag;String transfer=attachment.optString("transfer_id","");if(transfer.isEmpty()||SereinAttachmentStore.existing(this,accountId,transfer,attachment.optString("filename","attachment"),attachment.optLong("size",-1))!=null||!inlineGifDownloads.add(transfer))continue;engine.downloadAttachment(attachment).whenComplete((file,error)->runOnUiThread(()->{inlineGifDownloads.remove(transfer);if(error==null&&started)render();}));}}}
