    private String localDayLabel(String timestamp){try{java.time.LocalDate date=java.time.Instant.parse(timestamp).atZone(java.time.ZoneId.systemDefault()).toLocalDate(),today=java.time.LocalDate.now();if(date.equals(today))return "Today";if(date.equals(today.minusDays(1)))return "Yesterday";return date.format(java.time.format.DateTimeFormatter.ofPattern(date.getYear()==today.getYear()?"EEEE, MMM d":"EEEE, MMM d, yyyy",java.util.Locale.getDefault()));}catch(Exception ignored){return timestamp;}}
