    private void openAttachmentPreview(JSONObject attachment){if(engine==null)return;status.setText("Decrypting and saving the authenticated attachment…");engine.downloadAttachment(attachment).whenComplete((file,error)->runOnUiThread(()->{if(error!=null){toast(safeError(error));status.setText(engine.status());return;}status.setText(engine.status());showAttachmentViewer(file,attachment.optString("content_type","application/octet-stream"),attachment.optString("filename","Attachment"));}));}
    private void showAttachmentViewer(File file,String mime,String filename){
        if(file==null||!file.isFile()){toast("Downloaded attachment is unavailable.");return;}String type=mime==null?"application/octet-stream":mime.toLowerCase(java.util.Locale.ROOT);Dialog viewer=new Dialog(this);FrameLayout stage=new FrameLayout(this);stage.setBackgroundColor(0xFF050607);View content;
        if(type.startsWith("image/gif")||filename.toLowerCase(java.util.Locale.ROOT).endsWith(".gif")){try{content=new GifMovieView(this,file,0);}catch(Exception error){content=new ImageView(this);((ImageView)content).setImageBitmap(readScaledBitmap(file));((ImageView)content).setScaleType(ImageView.ScaleType.FIT_CENTER);}}
        else if(type.startsWith("image/")){ImageView image=new ImageView(this);image.setImageBitmap(readScaledBitmap(file));image.setScaleType(ImageView.ScaleType.FIT_CENTER);content=image;}
        else if(type.startsWith("video/")){android.widget.VideoView video=new android.widget.VideoView(this);video.setVideoURI(Uri.fromFile(file));android.widget.MediaController controls=new android.widget.MediaController(this);controls.setAnchorView(video);video.setMediaController(controls);video.setOnPreparedListener(player->{player.setLooping(false);video.start();});content=video;}
        else{try{SereinAttachmentStore.open(this,file,type);}catch(Exception error){toast(error.getMessage());}return;}
        final View previewContent=content;FrameLayout.LayoutParams body=new FrameLayout.LayoutParams(-1,-1);body.setMargins(dp(8),dp(92),dp(8),dp(62));stage.addView(previewContent,body);TextView name=SereinUi.text(this,filename,14,0xFFFFFFFF,true);name.setGravity(Gravity.CENTER_VERTICAL);name.setMaxLines(1);name.setEllipsize(android.text.TextUtils.TruncateAt.MIDDLE);FrameLayout.LayoutParams nameParams=new FrameLayout.LayoutParams(-1,dp(52),Gravity.TOP);nameParams.setMargins(dp(14),0,dp(60),0);stage.addView(name,nameParams);TextView properties=SereinUi.text(this,mime+" · "+formatBytes(file.length())+"\n"+file.getAbsolutePath(),10,0xCCFFFFFF,false);properties.setMaxLines(2);properties.setEllipsize(android.text.TextUtils.TruncateAt.MIDDLE);FrameLayout.LayoutParams propertyParams=new FrameLayout.LayoutParams(-1,dp(42),Gravity.TOP);propertyParams.setMargins(dp(14),dp(45),dp(56),0);stage.addView(properties,propertyParams);Button done=SereinUi.button(this,"×",false);done.setTextSize(22);FrameLayout.LayoutParams closeParams=new FrameLayout.LayoutParams(dp(48),dp(48),Gravity.TOP|Gravity.RIGHT);stage.addView(done,closeParams);done.setOnClickListener(v->viewer.dismiss());viewer.setContentView(stage);viewer.setCancelable(true);viewer.show();if(viewer.getWindow()!=null)viewer.getWindow().setLayout(-1,-1);viewer.setOnDismissListener(dialog->{if(previewContent instanceof android.widget.VideoView)((android.widget.VideoView)previewContent).stopPlayback();if(previewContent instanceof GifMovieView)((GifMovieView)previewContent).stop();});
    }
    private android.graphics.Bitmap readMediaThumbnail(File file){android.graphics.BitmapFactory.Options bounds=new android.graphics.BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeFile(file.getAbsolutePath(),bounds);android.graphics.BitmapFactory.Options options=new android.graphics.BitmapFactory.Options();int sample=1;while(Math.max(bounds.outWidth,bounds.outHeight)/sample>192&&sample<64)sample*=2;options.inSampleSize=sample;return BitmapFactory.decodeFile(file.getAbsolutePath(),options);}
    private android.graphics.Bitmap readScaledBitmap(File file){android.graphics.BitmapFactory.Options bounds=new android.graphics.BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeFile(file.getAbsolutePath(),bounds);android.graphics.BitmapFactory.Options options=new android.graphics.BitmapFactory.Options();options.inSampleSize=Math.max(1,Math.min(bounds.outWidth/1200, bounds.outHeight/1600));return BitmapFactory.decodeFile(file.getAbsolutePath(),options);}
    private static final class GifMovieView extends View {private final android.graphics.Movie movie;private final long started=android.os.SystemClock.uptimeMillis();private final int autoplayLoops;private final boolean staticFrame;private final Runnable onAutoplayFinished;private boolean running=true;GifMovieView(Context context,File file)throws Exception{this(context,file,0,false,null);}GifMovieView(Context context,File file,int autoplayLoops)throws Exception{this(context,file,autoplayLoops,false,null);}GifMovieView(Context context,File file,int autoplayLoops,boolean staticFrame,Runnable finished)throws Exception{super(context);this.autoplayLoops=Math.max(0,autoplayLoops);this.staticFrame=staticFrame;this.running=!staticFrame;this.onAutoplayFinished=finished;if(file.length()>16L*1024*1024)throw new java.io.IOException("GIF is too large for the animated in-app viewer.");try(InputStream in=new FileInputStream(file)){movie=android.graphics.Movie.decodeStream(in);}if(movie==null)throw new java.io.IOException("GIF preview is unavailable.");}void stop(){running=false;}@Override protected void onDraw(android.graphics.Canvas canvas){super.onDraw(canvas);if(!running&&!staticFrame)return;int duration=Math.max(1,movie.duration());long elapsed=android.os.SystemClock.uptimeMillis()-started;if(staticFrame)movie.setTime(duration-1);else if(autoplayLoops>0&&elapsed>=duration*(long)autoplayLoops){movie.setTime(duration-1);running=false;if(onAutoplayFinished!=null)onAutoplayFinished.run();}else movie.setTime((int)(elapsed%duration));float scale=Math.min((float)getWidth()/Math.max(1,movie.width()),(float)getHeight()/Math.max(1,movie.height()));float left=(getWidth()-movie.width()*scale)/2f,top=(getHeight()-movie.height()*scale)/2f;canvas.save();canvas.translate(left,top);canvas.scale(scale,scale);movie.draw(canvas,0,0);canvas.restore();if(running)postInvalidateDelayed(40);}}
    private void cancelHistorySyncWithConfirmation(JSONObject request){new AlertDialog.Builder(this).setTitle("Cancel history sync?").setMessage("Any encrypted relay batches will be deleted. Local history will not be changed.").setNegativeButton("Keep request",null).setPositiveButton("Cancel request",(d,w)->engine.cancelHistorySync(request).whenComplete((ignored,failure)->runOnUiThread(()->status.setText(failure==null?"History sync cancelled.":safeError(failure))))).show();}
    private void showHistorySyncDialog(){if(engine==null||!engine.ready()){toast("Secure device setup is still starting.");return;}status.setText("Checking main-device history sync…");api.ownDeviceKeyDirectory().thenCombine(engine.historySyncRequests(),(directory,requests)->new Object[]{directory,requests}).whenComplete((result,error)->runOnUiThread(()->{if(error!=null){status.setText(safeError(error));return;}JSONObject directory=(JSONObject)result[0];JSONArray requests=(JSONArray)result[1];String mainId=directory.isNull("main_device_id")?"":directory.optString("main_device_id","");boolean isMain;String currentDevice=directory.optString("current_device_id","");isMain=!mainId.isEmpty()&&mainId.equals(currentDevice);java.util.ArrayList<String> labels=new java.util.ArrayList<>();java.util.ArrayList<Runnable> actions=new java.util.ArrayList<>();if(isMain){for(int i=0;i<requests.length();i++){JSONObject request=requests.optJSONObject(i);if(request==null||!request.optBoolean("caller_is_main")||!("pending".equals(request.optString("status"))||"transferring".equals(request.optString("status"))||"ready".equals(request.optString("status"))))continue;final JSONObject target=request;if("ready".equals(target.optString("status"))){labels.add("Cancel ready sync to "+target.optString("child_device_name","child device"));actions.add(()->cancelHistorySyncWithConfirmation(target));}else{labels.add("Sync everything to "+target.optString("child_device_name","child device"));actions.add(()->{new AlertDialog.Builder(this).setTitle("Send local history?").setMessage("Only decrypted local timeline rows are included. Ratchet snapshots, settings, keys, and attachment bytes are excluded. The selected child must import explicitly; server relay expires within 24 hours.").setNegativeButton("Cancel",null).setPositiveButton("Sync",(d,w)->engine.sendHistorySync(target).whenComplete((ignored,failure)->runOnUiThread(()->{status.setText(failure==null?"History encrypted and sent to child.":safeError(failure));if(failure==null)toast("History sync batches sent.");}))).show();});actions.add(()->cancelHistorySyncWithConfirmation(target));labels.add("Cancel request to "+target.optString("child_device_name","child device"));}}}else{if(!mainId.isEmpty()){labels.add("Request ‘Sync everything’ from main");actions.add(()->engine.requestHistorySync().whenComplete((created,failure)->runOnUiThread(()->{status.setText(failure==null?"Request sent. The main device must explicitly sync.":safeError(failure));if(failure==null)toast("History request sent to the designated main device.");})));}for(int i=0;i<requests.length();i++){JSONObject request=requests.optJSONObject(i);if(request==null||request.optBoolean("caller_is_main"))continue;final JSONObject target=request;if("ready".equals(target.optString("status"))){labels.add("Import ready history ("+target.optInt("batch_count")+" batches)");actions.add(()->engine.receiveHistorySync(target).whenComplete((added,failure)->runOnUiThread(()->{status.setText(failure==null?"Imported "+added+" history records.":safeError(failure));if(failure==null)toast("History imported; ratchet state was not changed.");render();})));}if(java.util.Arrays.asList("pending","transferring","ready").contains(target.optString("status"))){labels.add("Cancel history sync request");actions.add(()->new AlertDialog.Builder(this).setTitle("Cancel history sync?").setMessage("Any encrypted relay batches will be deleted. Local history will not be changed.").setNegativeButton("Keep request",null).setPositiveButton("Cancel request",(d,w)->engine.cancelHistorySync(target).whenComplete((ignored,failure)->runOnUiThread(()->status.setText(failure==null?"History sync cancelled.":safeError(failure))))).show());}}}String preferredMobile=directory.isNull("preferred_mobile_device_id")?"":directory.optString("preferred_mobile_device_id","");if(mainId.isEmpty()&&(preferredMobile.isEmpty()||preferredMobile.equals(currentDevice))){labels.add("Promote this device to main (future history only)");actions.add(()->new AlertDialog.Builder(this).setTitle("Promote this device?").setMessage("This only authorizes future explicit history sync. It cannot recover a former main device’s older history.").setNegativeButton("Cancel",null).setPositiveButton("Promote",(d,w)->engine.promoteCurrentDeviceToMain().whenComplete((reply,failure)->runOnUiThread(()->status.setText(failure==null?"Main device designated for future sync.":safeError(failure))))).show());}if(mainId.isEmpty()&&!preferredMobile.isEmpty()&&!preferredMobile.equals(currentDevice))labels.add("The oldest active mobile device has priority for main");if(labels.isEmpty())labels.add("No active history-sync requests");AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Main-device history sync").setItems(labels.toArray(new String[0]),(d,index)->{if(index<actions.size())actions.get(index).run();}).setNeutralButton("Refresh",(d,w)->{d.dismiss();showHistorySyncDialog();}).setPositiveButton("Done",null).create();SereinUi.showStyledDialog(dialog,false);status.setText(isMain?"This device is the designated "+("android".equals(directory.optString("main_device_platform"))?"Android":"ios".equals(directory.optString("main_device_platform"))?"iOS":"")+" main history authority.":mainId.isEmpty()?(preferredMobile.isEmpty()?"No main device is designated; the oldest active mobile device is preferred.":preferredMobile.equals(currentDevice)?"This mobile device has priority. Explicitly promote it to enable future history sync.":"The oldest active mobile device has priority for main."):(directory.optBoolean("main_device_online")?"Designated main is online and available for explicit history sync. ":"History sync waits for the designated main device to come online. ")+"iOS and Android devices take priority over browser devices.");}));}
    private void showPeerKeys(){
        if(engine==null)return;List<SereinChatEngine.Peer> peers=engine.peers();LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);list.setPadding(dp(12),dp(8),dp(12),dp(8));
        TextView intro=SereinUi.text(this,"The app checks both public-key layers against their combined fingerprint and pins first-seen keys on this device. A changed key is blocked.",12,SereinUi.muted(this),false);list.addView(intro,SereinUi.margin(this,-1,-2,0,0,0,12));
        if(peers.isEmpty()){TextView empty=SereinUi.text(this,engine.status(),12,SereinUi.muted(this),false);list.addView(empty);}
        for(SereinChatEngine.Peer peer:peers){
            LinearLayout card=SereinUi.card(this);TextView title=SereinUi.text(this,peer.name,14,SereinUi.text(this),true);card.addView(title);
            TextView state=SereinUi.text(this,peer.trusted?"App checked · locally pinned":"Key changed or capability downgraded · sending blocked",11,peer.trusted?SereinUi.accent(this):SereinTokens.WARNING_LIGHT,false);card.addView(state,SereinUi.margin(this,-1,-2,0,4,0,4));
            TextView capability=SereinUi.text(this,"Both key layers checked · "+(peer.ratchetVersion>=3?"ratchet v3 capability":"static v2 capability"),10,SereinUi.muted(this),false);card.addView(capability,SereinUi.margin(this,-1,-2,0,4,0,6));
            TextView fingerprint=SereinUi.text(this,peer.fingerprint.replaceAll("(.{4})","$1 ").trim(),11,SereinUi.text(this),false);fingerprint.setTextIsSelectable(true);fingerprint.setVisibility(View.GONE);card.addView(fingerprint);
            String previous=engine.previousFingerprint(peer.deviceId);if(!previous.isEmpty()&&!previous.equals(peer.fingerprint)){TextView old=SereinUi.text(this,"Previously pinned: "+previous.replaceAll("(.{4})","$1 ").trim(),10,SereinTokens.WARNING_LIGHT,false);old.setTextIsSelectable(true);old.setVisibility(View.GONE);card.addView(old);}
            Button details=SereinUi.button(this,"Show combined fingerprint",false);card.addView(details,SereinUi.margin(this,-1,40,0,8,0,0));details.setOnClickListener(v->{boolean show=fingerprint.getVisibility()!=View.VISIBLE;fingerprint.setVisibility(show?View.VISIBLE:View.GONE);for(int i=0;i<card.getChildCount();i++){View child=card.getChildAt(i);if(child instanceof TextView&&((TextView)child).getText().toString().startsWith("Previously pinned:"))child.setVisibility(show?View.VISIBLE:View.GONE);}details.setText(show?"Hide fingerprint":"Show combined fingerprint");});list.addView(card,SereinUi.margin(this,-1,-2,0,0,0,9));
        }
        ScrollView scroll=new ScrollView(this);scroll.addView(list);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Encryption status · "+peers.size()+" device"+(peers.size()==1?"":"s")).setView(scroll).setNeutralButton("Rotate this device’s keys",(d,w)->new AlertDialog.Builder(this).setTitle("Rotate encryption keys?").setMessage("A fresh ECDH key bundle will be signed by this device’s separate continuity key. Rotation waits until every queued old-key message is acknowledged or expires. Existing local history and fingerprint-namespaced ratchet snapshots are retained.").setNegativeButton("Cancel",null).setPositiveButton("Rotate",(confirm,which)->{status.setText("Proving signed device-key continuity…");engine.rotateDeviceKeys().whenComplete((ignored,error)->runOnUiThread(()->{status.setText(error==null?"Device encryption keys rotated with continuity proof.":safeError(error));if(error==null)Toast.makeText(this,"Device encryption keys rotated.",Toast.LENGTH_LONG).show();render();}));}).show()).setPositiveButton("Done",null).create();SereinUi.showStyledDialog(dialog,false);
    }
    private String safeError(Throwable error){Throwable value=error;while(value.getCause()!=null&&(value instanceof java.util.concurrent.CompletionException||value instanceof java.util.concurrent.ExecutionException))value=value.getCause();String message=value.getMessage();return message==null?"Encrypted operation failed; no cleartext was sent.":message;}
    private void toast(String value){Toast.makeText(this,value==null?"Operation failed.":value,Toast.LENGTH_LONG).show();}
    @Override protected void onResume(){super.onResume();started=true;if(engine!=null&&engine.ready())pollTask.run();}
    @Override protected void onDestroy(){started=false;handler.removeCallbacks(pollTask);if(gifDialog!=null&&gifDialog.isShowing())gifDialog.dismiss();gifExecutor.shutdownNow();for(android.graphics.Bitmap bitmap:gifPreviewCache.values())bitmap.recycle();gifPreviewCache.clear();super.onDestroy();}
    @Override protected void onPause(){started=false;handler.removeCallbacks(pollTask);super.onPause();}
